(x, y, t) => {
  const cx = 240, cy = 120;
  const masses = [
    [160+Math.sin(t*0.4)*90, 80+Math.cos(t*0.3)*60, 1.8],
    [320+Math.cos(t*0.5)*80, 160+Math.sin(t*0.6)*70, 2.2],
    [240+Math.sin(t*0.25+2)*130, 120+Math.cos(t*0.4+1)*100, 2.5],
    [100+Math.cos(t*0.7+1)*60, 190+Math.sin(t*0.5+3)*50, 1.4],
    [380+Math.sin(t*0.35+4)*70, 50+Math.cos(t*0.8+2)*60, 1.6],
    [200+Math.cos(t*0.3+5)*100, 210+Math.sin(t*0.45)*80, 1.9],
    [400+Math.sin(t*0.55)*50, 180+Math.cos(t*0.65)*40, 1.2]
  ];
  let gx = 0, gy = 0, pe = 0;
  for (const [mx, my, m] of masses) {
    const dx = mx - x, dy = my - y;
    const d2 = dx*dx + dy*dy + 400;
    const f = m * 800 / d2;
    gx += dx * f / Math.sqrt(d2);
    gy += dy * f / Math.sqrt(d2);
    pe -= m / Math.sqrt(d2);
  }
  const ke = (gx*gx + gy*gy) * 0.0001;
  const totalE = pe + ke;
  const flowAng = Math.atan2(gy, gx);
  const flowMag = Math.sqrt(gx*gx + gy*gy);
  const warp = flowMag * 0.08;
  const wx = Math.sin(flowAng*3 + t*0.6) * warp + Math.sin(x*0.02+y*0.015+t*0.5) * 8;
  const wy = Math.cos(flowAng*3 + t*0.6) * warp + Math.cos(x*0.018-y*0.02+t*0.45) * 8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.12, 2.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.14, 2.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.09, 2.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.16, 2.0],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.10, 3.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.13, 2.3]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.6 + t*sp*0.5 + 2.0);
  }
  const act = aS/6, inh = iS/6;
  const bg = (Math.sin(sx*0.05+sy*0.03+t*1.0) + Math.sin(sx*0.035-sy*0.045+t*1.3))/2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.06-ang*4-t*2.0) + Math.sin(dist*0.045+ang*5-t*1.6))*0.35;
  const energyBoost = Math.tanh(totalE * 3.0) * 0.4;
  const raw = act - inh*0.65 + bg*0.25 + spiral + energyBoost;
  const reaction = Math.tanh(raw * 3.0);
  const cell = Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18) + Math.sin((sx+sy)*0.12+t*1.2)*0.4)*2.0)*0.25;
  const edge = Math.abs(reaction) > 0.55 ? 1.4 : 0.7;
  const glow = Math.max(0, Math.abs(reaction) - 0.4) * 2.5;
  const v = (reaction*0.7 + cell*0.3) * edge + glow * 0.15;
  const n = v * 0.5 + 0.5;
  const pal = [
    [2, 2, 12], [5, 10, 45], [10, 40, 80], [0, 180, 220],
    [0, 255, 200], [180, 255, 50], [255, 220, 0], [255, 80, 180],
    [200, 0, 255], [100, 0, 180], [30, 0, 60], [2, 2, 12]
  ];
  const idx = Math.max(0, Math.min(n * (pal.length-1), pal.length-1.001));
  const i = idx | 0, f = idx - i;
  const lum = 0.85 + glow * 0.6;
  const neon = 1.0 + Math.max(0, glow - 0.3) * 0.8;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*neon)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*neon)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*neon)|0
  ];
}
